body:
// BEGIN D1 SIMULATION OBSERVATION BODY
assign d1_available=D1_OBSERVE;
generate if(D1_OBSERVE)begin:g_d1_observe
 assign d1_me_ready=dut.u_tile.u_core.me_ready;
 assign d1_kv_ok=dut.u_tile.u_core.kv_ok;
 assign d1_kvd_v=dut.u_tile.u_core.kvd_v;
 assign d1_win_idle=dut.u_tile.u_core.win_idle;
 assign d1_desc_accept=dut.g_packed_kv.u_desc_life.desc_accept;
 assign d1_desc_generation=dut.g_packed_kv.u_desc_life.desc_gen;
 w17_D1_source_observer #(.ENABLED(1)) observer(
  .clk(clk),.rst_n(rst_n),.fault((|dbg_fs) || (|fault)),
  .accept(dut.g_packed_kv.w_v[dut.WIN_STACK] && dut.g_packed_kv.w_rdy[dut.WIN_STACK]),
  .we(dut.g_packed_kv.w_we[dut.WIN_STACK]),
  .state(dut.g_packed_kv.g_window_hbm_attention.u_source.u_window.state),
  .address(dut.g_packed_kv.w_addr[dut.WIN_STACK*30+:30]),
  .tag(dut.g_packed_kv.w_tag[dut.WIN_STACK*16+:16]),
  .response(dut.g_packed_kv.w_sv[dut.WIN_STACK] && dut.g_packed_kv.w_srdy[dut.WIN_STACK]),
  .response_tag(dut.g_packed_kv.w_s_tag[dut.WIN_STACK*16+:16]),
  .beat(dut.g_packed_kv.w_s_beat[dut.WIN_STACK*4+:4]),
  .poison(dut.g_packed_kv.g_window_hbm_attention.u_source.u_window.response_poison),
  .write_done(dut.g_packed_kv.w_wdone[dut.WIN_STACK]),
  .read_accepts(d1_read_accepts),.read_returns(d1_read_returns),
  .write_accepts(d1_write_accepts),.write_acks(d1_write_acks),.violations(d1_violations),
  .pending(d1_pending),.pending_address(d1_pending_address),.pending_tag(d1_pending_tag));
end else begin:g_d1_unavailable
 assign d1_me_ready=0;assign d1_kv_ok=0;assign d1_kvd_v=0;assign d1_win_idle=0;
 assign d1_desc_accept=0;assign d1_desc_generation=0;
 assign d1_read_accepts=0;assign d1_read_returns=0;assign d1_write_accepts=0;assign d1_write_acks=0;
 assign d1_violations=0;assign d1_pending=0;assign d1_pending_address=0;assign d1_pending_tag=0;
end endgenerate
// END D1 SIMULATION OBSERVATION BODY
